from __future__ import annotations

import yaml
from pathlib import Path


POLICY_DIR = Path(__file__).resolve().parents[2] / "policy"


def _load_policy(agent: str) -> dict:
    policy_file = POLICY_DIR / f"{agent.rstrip('_0123456789')}.yaml"
    if not policy_file.exists():
        return {}
    with open(policy_file) as f:
        return yaml.safe_load(f) or {}


def check_call(agent: str, tool: str, target_host: str, args: dict) -> str | None:
    policy = _load_policy(agent)
    if not policy:
        return None

    tools = policy.get("tools", [])
    if tool not in tools:
        return f"Tool {tool} not in approved tools list"

    destinations = policy.get("destinations", {})
    approved = destinations.get(tool, [])
    if target_host not in approved:
        return f"Target host {target_host} not in approved destinations for {tool}"

    return None


def filter_result(agent: str, tool: str, text: str) -> str:
    return text

